"""Guards for comparing bare starts against production-loot prepared high-floor runs."""
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
capture = (ROOT / "tests/stage92_floor_progression_capture.gd").read_text(encoding="utf-8")
scene = (ROOT / "tests/stage92_prepared_floor_progression_runner.tscn").read_text(encoding="utf-8")
reporter = (ROOT / "tools/geared_floor_progression_report.py").read_text(encoding="utf-8")
workflow = (ROOT.parent / ".github/workflows/abyssloop-web.yml").read_text(encoding="utf-8")

checks = {
    "prepared sample is limited to high floors 5-8 with matched fixed seeds": "PREPARED_FLOOR_IDS: Array[int] = [5, 6, 7, 8]" in capture and "FIXED_SEEDS: Array[int] = [91001, 91003, 91007]" in capture,
    "separate runner enables the previous-floor loadout mode": "prepare_previous_floor_loadout = true" in scene,
    "loadout pieces are generated by production roll_item using prior-floor context": "inventory_system.roll_item(loadout_rng, 6, 7, 0.08, previous_floor)" in capture and "var previous_floor := maxi(1, floor_id - 1)" in capture,
    "all six slots are registered and equipped through production GameState APIs": "GameState.register_item(item)" in capture and 'GameState.equip_item(str(item.get("id", "")))' in capture and "InventorySystemScript.EQUIPMENT_SLOTS.size()" in capture,
    "test does not override generated equipment or hero combat stats": all(token not in capture for token in ['item["attack"] =', 'item["defense"] =', 'manager.hero["attack"] =', 'manager.hero["hp"] =']),
    "prepared run records actual loadout rarity, rank, archetype and power": all(token in capture for token in ['"rarity": str(item.get("rarity"', '"rank": int(item.get("rank"', '"archetype": str(item.get("archetype"', '"capture_equipment_power"']),
    "prepared output is separate from clean-start floor capture": "STAGE92_PREPARED_FLOOR_PROGRESSION.json" in capture and "STAGE92_FLOOR_PROGRESSION.json" in capture,
    "comparison report validates six slots on each prepared high-floor run": 'set(loadout) != {"weapon", "helmet", "armor", "shield", "amulet", "core"}' in reporter and '"capture_loadout_completed_slots"' in reporter,
    "report compares clean and prepared outcomes without claiming final balance": 'Возвраты без экипировки' in reporter and 'Возвраты с экипировкой' in reporter and "не даёт статистически окончательного вердикта" in reporter,
    "CI runs the prepared sample and generates its comparison report": "Capture Stage92 prepared high-floor loadout matrix" in workflow and "stage92_prepared_floor_progression_runner.tscn" in workflow and "geared_floor_progression_report.py" in workflow,
}
failed = [name for name, passed in checks.items() if not passed]
for name, passed in checks.items():
    print(f"{'PASS' if passed else 'FAIL'}: {name}")
if failed:
    raise SystemExit("STAGE92 PREPARED LOADOUT REGRESSION FAILED: " + ", ".join(failed))
print(f"STAGE92 PREPARED LOADOUT REGRESSION PASSED: {len(checks)}/{len(checks)} checks")
print("Source guard only; matched Godot engine runs are required for interpretation.")
